        $weight = (int) ($styles[(int) ($run['styleIndex'] ?? -1)]['fontWeight'] ?? 400);
        $text = nl2br(esc_html($text));
        $html .= $weight >= 700 ? '<strong>' . $text . '</strong>' : $text;
        $offset = $end;
    }
