function ra_set_owned_price(WC_Product $product, string $price, array $provenance): void {
    $id = $product->get_id();
    if (ra_owned_meta_can_update($id, '_regular_price', $price)) {
        $product->set_regular_price($price);
        $product->set_price($price);
